// Generates the generated stylesheets of @gjuoun/bigface-ui from the two palettes and the role maps:
//
//   src/styles/tokens.css     the Bigface palette as --bf-* (the dark default)
//   src/themes/_reset.css     optional --theme-* keys → initial, per [data-theme] scope
//   src/themes/<id>.css       one file per theme: a light block and a dark block
//
//   bun run --cwd packages/ui theme:sync    rewrite every generated file in place
//   bun run --cwd packages/ui theme:check   fail when any of them is stale (CI uses this)
//
// The palettes stay the single source of colour: a theme names palette colours (src/themes/roles.ts),
// never hexes, so both modes come out of one role map and a palette edit flows through both.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import {
	OPTIONAL,
	REQUIRED,
	THEMES,
	type Theme,
	type Value,
} from "../src/themes/roles.ts";

export interface PaletteLike {
	colors: Record<string, { hex: string }>;
	ansi: Record<string, { hex: string }>;
}

const kebab = (name: string): string =>
	name
		.replace(/([a-z0-9])([A-Z])/g, "$1-$2")
		.replace(/_/g, "-")
		.toLowerCase();

/** The exact text of tokens.css for a palette. Deterministic: input order only, no timestamps. */
export function renderTokens(palette: PaletteLike): string {
	const colors = Object.entries(palette.colors).map(
		([name, c]) => "  --bf-" + kebab(name) + ": " + c.hex.toLowerCase() + ";",
	);
	const ansi = Object.entries(palette.ansi).map(
		([name, c]) =>
			"  --bf-ansi-" + kebab(name) + ": " + c.hex.toLowerCase() + ";",
	);
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from palette/bigface.json. Do not edit.",
		"   Bigface's dark theme: import it after theme.css, or skip it and set your own --bf-* values. */",
		":root {",
		...colors,
		...ansi,
		"  --ink-on-bright: var(--bf-bg);",
		"}",
		"",
	].join("\n");
}

const here = import.meta.dir;
export const tokensPath = join(here, "../src/styles/tokens.css");
export const themesDir = join(here, "../src/themes");
const palettePath = join(here, "../../bigface-tokens/palette/bigface.json");
const lightPalettePath = join(
	here,
	"../../bigface-tokens/palette/bigface-light.json",
);

const hexOf = (palette: PaletteLike, name: string): string => {
	const c = palette.colors[name] ?? palette.ansi[name];
	if (!c) throw new Error("no palette colour named " + name);
	return c.hex.toLowerCase();
};

const toLinear = (v: number): number => {
	const c = v / 255;
	return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
};

/** Two palette colours mixed in OKLab, as one hex: the tint a role asks for, computed here. */
export function mixHex(a: string, pct: number, b: string): string {
	const lab = (h: string) => {
		const [r, g, bb] = [1, 3, 5].map((i) => toLinear(Number.parseInt(h.slice(i, i + 2), 16)));
		const l = Math.cbrt(0.4122214708 * (r as number) + 0.5363325363 * (g as number) + 0.0514459929 * (bb as number));
		const m = Math.cbrt(0.2119034982 * (r as number) + 0.6806995451 * (g as number) + 0.1073969566 * (bb as number));
		const s = Math.cbrt(0.0883024619 * (r as number) + 0.2817188376 * (g as number) + 0.6299787005 * (bb as number));
		return [
			0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
			1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
			0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
		];
	};
	const x = lab(a);
	const y = lab(b);
	const t = pct / 100;
	const L = (x[0] as number) * t + (y[0] as number) * (1 - t);
	const A = (x[1] as number) * t + (y[1] as number) * (1 - t);
	const B = (x[2] as number) * t + (y[2] as number) * (1 - t);
	const l = (L + 0.3963377774 * A + 0.2158037573 * B) ** 3;
	const m = (L - 0.1055613458 * A - 0.0638541728 * B) ** 3;
	const s = (L - 0.0894841775 * A - 1.291485548 * B) ** 3;
	const enc = (v: number) => {
		const c = v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055;
		return Math.round(Math.min(1, Math.max(0, c)) * 255).toString(16).padStart(2, "0");
	};
	return (
		"#" +
		[
			4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
			-1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
			-0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
		]
			.map(enc)
			.join("")
	);
}

/**
 * One role value as CSS: a palette hex, a tint mixed here (OKLab, two palette colours), or a literal.
 *
 * The mix is computed rather than emitted as color-mix(): a browser would do the same maths, and a
 * minifier would precompute it anyway — as an oklab() literal the colour guard cannot recognise.
 * Computing it keeps every colour in the output a value the guard can check.
 */
export function cssValue(
	v: Value,
	palette: PaletteLike,
	dark?: PaletteLike,
	mode: "light" | "dark" = "dark",
): string {
	if (typeof v === "string") return v;
	if ("light" in v) return cssValue(mode === "light" ? v.light : v.dark, palette, dark, mode);
	if ("color" in v) {
		const chosen = v.palette === "dark" && dark ? dark : palette;
		return hexOf(chosen, v.color);
	}
	const [a, pct, b] = v.mix;
	return mixHex(hexOf(palette, a), pct, hexOf(palette, b));
}

/** A theme's block for one mode, in contract order: every required key, then every optional key. */
export function renderBlock(
	theme: Theme,
	palette: PaletteLike,
	dark?: PaletteLike,
	mode: "light" | "dark" = "dark",
): string {
	const keys = [...REQUIRED, ...OPTIONAL] as string[];
	const missing = keys.filter((k) => !(k in theme.roles));
	const extra = Object.keys(theme.roles).filter((k) => !keys.includes(k));
	if (missing.length)
		throw new Error(theme.id + ": missing roles " + missing.join(", "));
	if (extra.length)
		throw new Error(theme.id + ": unknown roles " + extra.join(", "));
	return keys
		.map(
			(k) =>
				"  --theme-" +
				k +
				": " +
				cssValue(theme.roles[k] as Value, palette, dark, mode) +
				";",
		)
		.join("\n");
}

/** Light selectors, dark selectors (the wiki's three-part rule), then the two blocks. */
export function renderThemeFile(
	theme: Theme,
	dark: PaletteLike,
	light: PaletteLike,
): string {
	const own = '[data-theme="' + theme.id + '"]';
	const lightSel = theme.isDefault ? ":root:not([data-theme]),\n" + own : own;
	const darkSel = [
		...(theme.isDefault ? [':root:not([data-theme])[data-mode="dark"]'] : []),
		own + '[data-mode="dark"]',
		'[data-mode="dark"] ' + own + ':not([data-mode="light"])',
	].join(",\n");
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from src/themes/roles.ts and the two palettes.",
		"   Do not edit: change the role map, then run theme:sync again. */",
		"",
		lightSel + " {",
		renderBlock(theme, light, dark, "light"),
		"}",
		"",
		darkSel + " {",
		renderBlock(theme, dark, dark, "dark"),
		"}",
		"",
	].join("\n");
}

/** _reset.css: optional keys go back to the contract default inside every theme scope. */
export function renderReset(): string {
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from contract.json. Do not edit.",
		"   Custom properties inherit, so a nested theme scope would otherwise keep the outer theme's",
		"   optional values. initial is the guaranteed-invalid value: the mapping's var() fallback wins. */",
		"",
		"[data-theme] {",
		...OPTIONAL.map((k) => "  --theme-" + k + ": initial;"),
		"}",
		"",
	].join("\n");
}

/**
 * _light.css: the palette names (--bf-*) re-declared for light scopes. The site writes the dark values
 * inline on <html>, so any bg-bf- or border-bf- utility inside a light theme scope would otherwise paint a
 * DARK palette colour on paper. This is the pipeline's answer: one generated block, both palettes.
 */
export function renderLightAliases(light: PaletteLike, dark: PaletteLike): string {
	const colour = ([name, c]: [string, { hex: string }]) =>
		"  --bf-" + kebab(name) + ": " + c.hex.toLowerCase() + ";";
	const ansi = ([name, c]: [string, { hex: string }]) =>
		"  --bf-ansi-" + kebab(name) + ": " + c.hex.toLowerCase() + ";";
	return [
		"/* Generated by packages/ui/scripts/gen-tokens.ts from palette/bigface-light.json. Do not edit.",
		"   The palette names every --bf-* utility reads, re-declared for a light scope so no dark-palette",
		"   value can reach a paper surface. */",
		'[data-mode="light"] {',
		...Object.entries(light.colors).map(colour),
		...Object.entries(light.ansi).map(ansi),
		// A bright plate takes dark ink in BOTH modes; the light palette's own bg is the plate, not the ink.
		"  --ink-on-bright: " + dark.colors.bg.hex.toLowerCase() + ";",
		"}",
		"",
	].join("\n");
}

/** Every file theme:sync writes, as path → contents. */
export function renderAll(
	dark: PaletteLike,
	light: PaletteLike,
): Record<string, string> {
	const files: Record<string, string> = {
		[tokensPath]: renderTokens(dark),
		[join(themesDir, "_reset.css")]: renderReset(),
		[join(themesDir, "_light.css")]: renderLightAliases(light, dark),
	};
	for (const theme of THEMES) {
		files[join(themesDir, theme.id + ".css")] = renderThemeFile(
			theme,
			dark,
			light,
		);
	}
	return files;
}

const read = (p: string) => JSON.parse(readFileSync(p, "utf8")) as PaletteLike;

if (import.meta.main) {
	const files = renderAll(read(palettePath), read(lightPalettePath));
	const check = process.argv.includes("--check");
	let stale = 0;
	for (const [path, next] of Object.entries(files)) {
		const current = existsSync(path) ? readFileSync(path, "utf8") : "";
		if (!check) {
			writeFileSync(path, next);
			console.log("wrote " + path);
			continue;
		}
		if (current !== next) {
			console.error("stale: " + path);
			stale++;
		}
	}
	if (check) {
		if (stale) {
			console.error(stale + " file(s) stale: run theme:sync");
			process.exit(1);
		}
		console.log(
			"theme files are up to date (" + Object.keys(files).length + ")",
		);
	}
}
